{
  "design": {
    "theme": "chalk",
    "picture_style": "illustration"
  },
  "flow": [
    {"slide": 1, "does": "Recall saying a name and age", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 2, "does": "Introduce the approved objectives", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Teach family nouns and possessives", "look_at": {"kind": "picture", "shows": "Family members grouped around a child"}, "teaches": [1]},
    {"slide": 4, "does": "Check possessive choice", "look_at": {"kind": "none", "shows": null}, "teaches": [1]},
    {"slide": 5, "does": "Correct the speaker-gender misconception", "look_at": {"kind": "picture", "shows": "A boy and a girl each standing beside their mother"}, "teaches": [1]},
    {"slide": 6, "does": "Model a name, age and personality description", "look_at": {"kind": "picture", "shows": "An imaginary brother with a friendly expression"}, "teaches": [2]},
    {"slide": 7, "does": "Try a closely matched description", "look_at": {"kind": "none", "shows": null}, "teaches": [2]},
    {"slide": 8, "does": "Teach masculine and feminine adjective agreement", "look_at": {"kind": "picture", "shows": "A brother and sister representing masculine and feminine nouns"}, "teaches": [2]},
    {"slide": 9, "does": "Check agreement through sentence choices", "look_at": {"kind": "none", "shows": null}, "teaches": [2]},
    {"slide": 10, "does": "Model a connected family paragraph", "look_at": {"kind": "none", "shows": null}, "teaches": [3]},
    {"slide": 11, "does": "Try a closely matched family paragraph", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]},
    {"slide": 12, "does": "Apply the language to a new family", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]}
  ],
  "title": {
    "template": "title",
    "heading": "Ma famille",
    "lead": "My family\nRappelle-toi — Recall:\nHow do you say ‘My name is…’ and ‘I am 12 years old’?",
    "picture": null
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Les membres de ma famille",
      "lead": "Observe et répète — Look and repeat.",
      "points": [
        "mon père = my father · ma mère = my mother",
        "mon frère = my brother · ma sœur = my sister",
        "mes parents = my parents · mes grands-parents = my grandparents"
      ],
      "figure": {
        "shows": "An imaginary family with a central child, a father, mother, brother, sister and two grandparents, with the parents and grandparents visibly grouped",
        "must_see": ["central child", "father and mother", "brother and sister", "two older grandparents"],
        "subject": "generic"
      }
    },
    {
      "template": "hinge",
      "heading": "Choisis — Choose",
      "stem": "How do you say ‘my sister’?",
      "options": ["mon sœur", "ma sœur", "mes sœur"],
      "correct": 2
    },
    {
      "template": "compare",
      "heading": "Mon ou ma : who decides?",
      "columns": [
        {
          "label": "Un garçon — a boy",
          "text": "He says: ma mère.",
          "picture": {
            "shows": "A boy standing next to his mother",
            "must_see": ["young boy", "his mother"],
            "subject": "generic"
          }
        },
        {
          "label": "Une fille — a girl",
          "text": "She says: ma mère.",
          "picture": {
            "shows": "A girl standing next to her mother",
            "must_see": ["young girl", "her mother"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "visual-text",
      "heading": "Décrire mon frère",
      "lead": "Mon frère s’appelle Hugo.",
      "points": [
        {"label": "Nom — name", "text": "Il s’appelle Hugo."},
        {"label": "Âge — age", "text": "Il a treize ans."},
        {"label": "Caractère — personality", "text": "Il est gentil. = He is kind."}
      ],
      "figure": {
        "shows": "An imaginary teenage brother with a friendly expression",
        "must_see": ["teenage boy", "friendly smile"],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "À toi — Your turn",
      "questions": [
        "Brother: Léo. Write ‘My brother is called Léo’.",
        "Age: 14 (quatorze). Write ‘He is 14 years old’.",
        "Personality: kind (gentil). Write ‘He is kind’."
      ],
      "instruction": "Écris trois phrases — Write three sentences.",
      "picture": null
    },
    {
      "template": "compare",
      "heading": "Il est… / Elle est…",
      "columns": [
        {
          "label": "Mon frère — he",
          "text": "Il est gentil. = kind\nIl est amusant. = funny",
          "picture": {
            "shows": "An imaginary teenage brother",
            "must_see": ["teenage boy", "cheerful expression"],
            "subject": "generic"
          }
        },
        {
          "label": "Ma sœur — she",
          "text": "Elle est gentille. = kind\nElle est amusante. = funny",
          "picture": {
            "shows": "An imaginary teenage sister",
            "must_see": ["teenage girl", "cheerful expression"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "practice",
      "heading": "Accorde les adjectifs",
      "questions": [
        "Ma mère est gentil / gentille.",
        "Mon père est amusant / amusante.",
        "Translate: ‘My sister is funny’. Explain your adjective ending."
      ],
      "instruction": "Choisis, puis traduis — Choose, then translate.",
      "picture": null
    },
    {
      "template": "explain",
      "heading": "Un petit texte — A short text",
      "lead": "J’ai un frère. Je n’ai pas de sœur. Mon frère s’appelle Adam. Il a douze ans. Il est amusant.",
      "points": [
        {"label": "J’ai…", "text": "I have… : un frère / une sœur"},
        {"label": "Je n’ai pas de…", "text": "I do not have… : de frère / de sœur"}
      ]
    },
    {
      "template": "practice",
      "heading": "À toi : une autre famille",
      "questions": [
        "Write: ‘I have a brother. I do not have a sister’.",
        "Brother: Sami. Age: 11 (onze). Add his name and age.",
        "Personality: kind. Add a sentence about his personality."
      ],
      "instruction": "Écris un petit texte — Write a short paragraph.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Présente ta famille",
      "questions": [
        "Choose your own or an imaginary family. Say which siblings you have and do not have.",
        "Choose one family member. Give their relationship, name, age and one personality trait.",
        "Stretch: add a second family member with a different personality trait."
      ],
      "instruction": "Écris en français — Write in French. Check mon/ma/mes, il/elle and adjective endings.",
      "picture": null
    }
  ]
}
